      SUBROUTINE CONSECCC     CALCULATES PARTIALS AND CONSTRAINTS FOR SECOND-ORDER FITTINGCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM17B.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'TC2.CIN'CC     LOCAL VARIABLESC      REAL  TCS(11), TR(11,6,6), TS(11,21)CC---------------------------------------------------------------------      J = JCON      K = KCON      NP1 = NV1 + 1      IF (J .EQ. 18) GO TO 300      IF (J .GE. 0) GO TO 200CC     SECOND ORDER MATRIX ELEMENT CONSTRAINTC   70 IF (K .GT. 100) GO TO 150      IF (J .LT. - 20) J = J + 20      J = - J      KM = K      K = KM/10      M = KM - 10*K      IF (J .GT. 6) GO TO 900      IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      IF (M .LT. 1 .OR. M .GT. 6) GO TO 900      KM = K + M*(M-1)/2      DO 80 L1 = 1, NP1   80 A(L1) = 0.0      CW = 1.0/SD**2      FAC = UBEAM(K)*UBEAM(M)/UBEAM(J)      COC = TC2(J,KM)*FAC      IF (NV3 .LT. 1) RETURN      A(1) = DE0 - COCC      IF (NV1 .GE. 1) THEN        DO 130 N = 1, NV1        IF (R2VP(N)) THEN          A(N+1) = T2V(J,KM,N)*FAC        ENDIF  130   CONTINUE      ENDIF      CALL GATHER      NP1 = NV1 + 1      RETURNCC     THIRD-ORDER MATRIX ELEMENT CONSTRAINTC  150 IF (NORD3 .GE. 3) CALL CONDOR      RETURN     CC     MINIMIZATION OF CONTRIBUTION OF SECOND-ORDER ABERRATIONS TO BEAMC  200 IF (ACCEL) RETURN      CW = 1.0/(SD*UBEAM(J))**2C      SS = 0.0      IND = 0      DO 210 L2 = 1, 6      DO 210 L1 = 1, L2      IND = IND + 1      SS = SS + TC2(J,IND)*SI(L1,L2)  210 CONTINUE      TCS(1) = - SS      N1 = 1C      DO 220 L1 = 1, 6      INDA = 0      DO 220 K = 1, 6      SS = 0.0      DO 215 L2 = 1, K      INDA = INDA + 1      SS = SS + TC2(J,INDA)*SI(L1,L2)  215 CONTINUE      TR(1,L1,K) = - SS  220 CONTINUEC      IF (NV3 .LT. 1) GO TO 900      IF (NV1 .LT. 1) GO TO 251      DO 230 N = 1, NV1      SS = 0.0      IND = 0      DO 225 L2 = 1, 6      DO 225 L1 = 1, L2      IND = IND + 1      SS = SS + T2V(J,IND,N)*SI(L1,L2)  225 CONTINUE      TCS(N+1) = SS  230 CONTINUEC      DO 240 N = 1, NV1      DO 240 L1 = 1, 6      INDA = 0      DO 240 K = 1, 6      SS = 0.0      DO 235 L2 = 1, K      INDA = INDA + 1      SS = SS + T2V(J,INDA,N)*SI(L1,L2)  235 CONTINUE      TR(N+1,L1,K) = SS  240 CONTINUEC      NP1 = NV1 + 1      DO 250 N = 1, NP1      INDA = 0      DO 250 L1 = 1, 6      DO 250 K = 1, L1      INDA = INDA + 1      SS = 0.0      DO 245 L2 = 1, 6      SS = SS + TR(N,K,L2)*SI(L1,L2)  245 CONTINUE      TS(N,INDA) = SS  250 CONTINUEC  251 DO 260 N1 = 1, NP1      DO 260 N2 = 1, N1      IF (N1 .EQ. 1 .AND. N2 .EQ. 1) GO TO 260      TSST = TCS(N1)*TCS(N2)      DO 255 L1 = 1, 6      DO 255 L2 = 1, 6      TSST = TSST + TR(N1,L1,L2)*TR(N2,L2,L1)  255 CONTINUE      CA(N1,N2) = CA(N1,N2) + TSST*CW  260 CONTINUEC      N2 = 1      DO 270 N1 = 2, NP1      TSST = 0.0      DO 265 IND = 1, 21      TSST = TSST + TS(N1,IND)*TC2(J,IND)  265 CONTINUE      CA(N1,N2) = CA(N1,N2) - TSST*CW  270 CONTINUEC      DO 280 N1 = 2, NP1      DO 280 N2 = 2, N1      TSST = 0.0      DO 275 IND = 1, 21      TSST = TSST + TS(N1,IND)*T2V(J,IND,N2-1)  275 CONTINUE      CA(N1,N2) = CA(N1,N2) + TSST*CW  280 CONTINUEC      IF (NORD3 .GE. 3) CALL CONDOR      RETURNCC     LIMITATIONS ON SEXTUPOLE STRENGTHC  300 SEXLIM = .TRUE.      SEXMAX = SD*UNITI(9)C  900 RETURN      END